const Autocomplete = ({ suggestions, onSelect }) => {
  const [inputValue, setInputValue] = useState('');
  const [activeSuggestion, setActiveSuggestion] = useState(-1);
  const [suggestionsList, setSuggestionsList] = useState([]);

  useEffect(() => {
    const timer = setTimeout(() => {
      const suggestionList = suggestions.filter((suggestion) => {
        return suggestion.toLowerCase().includes(inputValue.toLowerCase());
      });
      setSuggestionsList(suggestionList);
    }, 500);

    return () => {
      clearTimeout(timer);
    };
  }, [inputValue, suggestions]);

  const renderSuggestions = () => {
    return suggestionsList.map((suggestion, index) => {
      return (
        <li
          key={index}
          onClick={() => onSelect(suggestion)}
          className={index === activeSuggestion ? 'active' : ''}
        >
          {suggestion}
        </li>
      );
    });
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        placeholder="Type to search..."
      />
      <ul className="suggestions-list">{renderSuggestions()}</ul>
    </div>
  );
};

export default Autocomplete;
```
